void cleanpath(pwd, to, clean)char *pwd, *to, *clean;/*   pwd is the current directory   to is the path to move to   clean points to where to put the resulting string   This routine is here because of slight diferrences   between OS9 and UNIX pathnames ('...' (for ../..), root   device).*/{   char buf[2*PATH];   char *root, *src, *dest;   if (to[0] != '/')   {      strncpy(buf, pwd, PATH-2);      strcat(buf, "/");   }   else      buf[0] = '\0';   strcat(buf, to);   src = buf;   dest = clean;   do      *dest++ = *src++;   while (*src != '\0' && *src != '/'); 		/* Copy root device */   root = dest;   while(*src != 0)   {      *dest++ = *src++; 	/* Copy delimiter */      if (src[0] == '.')         switch (src[1])         {            case '.':                           /* segment starts with "/.." */                /* for any '.' in excess of 1 back up 1 dir level */               src++;               while(*src != '\0' && *src++ == '.')                  if (dest-1 > root)                     for (--dest; dest[-1] != '/'; )                        --dest;               continue;            case '/':                               /* "/./" segment: ignore */               dest--;                                       /* Fall through */            case '\0':	                                /* path ends in "/." */               src++;               continue;            default:               break;                           /* Lint likes this construct */         }                        /* Copy next segment */         while (*src != '\0' && *src != '/')            *dest++ = *src++;		/* append new segment */   }   if(dest[-1] == '/')      --dest;   *dest = '\0';   }